package main

import (
	"gno.land/r/gov/dao"
	valset "gno.land/r/sys/validators/v0"
)

func main(cur realm) {
	r := valset.NewValidatorProposalRequest(
		cross(cur),
		[]valset.ValoperChange{
			valset.NewValoperChange(address("g1aeddlftlfk27ret5rf750d7w5dume3kcsm8r8m"), 60),
		},
		"Set validator gno-core-validator-1 to voting power 60",
		"Return gno-core-validator-1 to voting power 60: the other validators are signing again.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

// Package v180check is deployed on onyx after the v1.8.0-rc.1 halt: its
// addpkg checks that a canonical transaction is included, and its enable that
// GPASO's transactions are.
package v180check

func Render(_ string) string {
	return "# v1.8.0-rc.1 check\n\nDeployed and enabled after onyx's halt at 1203400.\n"
}

// Package e2ecanary is a throwaway realm proving an end-to-end publish on onyx.
package e2ecanary

// Render returns a fixed line naming the release and the submission time.
func Render(_ string) string {
	return "v1.8.0-rc.1 e2e 2026-11-17T15:57:18Z"
}

package home

// Render returns the profile page markdown served by gnoweb.
// gnoweb calls Render("") for /r/nym-transtangible420/home,
// which backs the profile at /u/nym-transtangible420.
func Render(path string) string {
	if path != "" {
		return "# nym-transtangible420\n\nNo such subpage: `" + path + "`\n"
	}
	return `# nym-transtangible420

> Building on Gno.land — deterministic, human-readable smart contracts.

## About

- **Name:** nym-transtangible420
- **Realm:** gno.land/r/nym-transtangible420/home
- **Status:** local dev — deploy to Onyx testnet pending (TODO #4)

## Links

- [gno.land profile](https://gno.land/u/nym-transtangible420)
- More links coming soon (placeholder).

---

*Rendered by a Gno realm. Deployed from the OpenClaw + Gnoland workspace.*
`
}

package home

import "testing"

func TestRenderRoot(t *testing.T) {
	out := Render("")
	if out == "" {
		t.Fatal("Render(\"\") returned empty markdown")
	}
	t.Log("Render(\"\") output:\n" + out)
}

func TestRenderSubpage(t *testing.T) {
	if Render("somepath") == "" {
		t.Fatal("Render(subpath) returned empty markdown")
	}
}
